```react
function Badge({count}) {
  const doubled = count * 2;
  return <p data-badge>{doubled} points</p>;
}
function App() {
  const [count, setCount] = React.useState(2);
  const [night, setNight] = React.useState(false);
  return <main data-night={night}>
    <Badge count={count} /><Badge count={count} />
    <button onClick={() => setCount(c => c + 1)}>Add point</button>
    <button onClick={() => setNight(n => !n)}>Change background</button>
  </main>;
}
```

