  const field = React.useRef(null);
  function focusField() {
    field.current?.focus();
  }
  return <main>
    <label htmlFor="study-topic">Study topic</label>
    <input id="study-topic" ref={field} />
    <button onClick={focusField}>Focus topic</button>
  </main>;
}
```

```react
function App() {
  const field = React.useRef(null);
  function focusField() {
    field.current?.blur();
  }
  return <main>
    <label htmlFor="study-topic">Study topic</label>
    <input id="study-topic" ref={field} />
    <button onClick={focusField}>Leave topic</button>
  </main>;
}
```
The changed handler removes focus instead of putting it on the input. Try focusing the field first, then activating the button. The visible label association remains unchanged.

