explanation:
```react
function TitleNote({topic}) {
  React.useEffect(() => {
    const previous = document.title;
    document.title = "Study: " + topic;
    return () => { document.title = previous; };
  }, [topic]);
  return <p>Topic: {topic}</p>;
}
function App() {
  const [topic, setTopic] = React.useState("Maps");
  const [visible, setVisible] = React.useState(true);
  return <main>
    <button onClick={() => setTopic("Birds")}>Choose Birds</button>
    <button onClick={() => setVisible(v => !v)}>Toggle note</button>
    {visible && <TitleNote topic={topic} />}
  </main>;
}
```

```react
function TitleNote({topic}) {
  React.useEffect(() => {
    const previous = document.title;
    document.title = "Study: " + topic;
    return () => { document.title = previous; };
  }, []);
  return <p>Topic: {topic}</p>;
}
function App() {
  const [topic, setTopic] = React.useState("Maps");
  const [visible, setVisible] = React.useState(true);
  return <main>
    <button onClick={() => setTopic("Birds")}>Choose Birds</button>
    <button onClick={() => setVisible(v => !v)}>Toggle note</button>
    {visible && <TitleNote topic={topic} />}
  </main>;
}
```
With [] the paragraph changes to Birds, but the document title remains Study: Maps. This is an intentionally stale changed case, not a recommended fix. Cleanup still runs when the note is removed.

