function TopicField({label}) {
  const id = React.useId();
  const hintId = id + "-hint";
  return <section>
    <label htmlFor={id}>{label}</label>
    <input id={id} aria-describedby={hintId} />
    <p id={hintId}>Use a short topic name.</p>
  </section>;
}
function App() {
  const [version, setVersion] = React.useState(0);
  return <main>
    <button onClick={() => setVersion(v => v + 1)}>Rerender {version}</button>
    <TopicField label="First topic" /><TopicField label="Second topic" />
  </main>;
}
```

```react
function TopicField({label}) {
  const id = "shared-topic";
  const hintId = id + "-hint";
  return <section>
    <label htmlFor={id}>{label}</label>
    <input id={id} aria-describedby={hintId} />
    <p id={hintId}>Use a short topic name.</p>
  </section>;
}
function App() {
  const [version, setVersion] = React.useState(0);
  return <main>
    <button onClick={() => setVersion(v => v + 1)}>Rerender {version}</button>
    <TopicField label="First topic" /><TopicField label="Second topic" />
  </main>;
}
```
Both changed instances now use shared-topic. Their labels and descriptions are no longer uniquely linked on the page, even though each component’s local strings match. A unique id must be unique across these rendered instances.

